insert into public.products (category_id, slug, name, sku, summary, price, stock, specs, image_url, image_credit, is_featured) values
  ((select id from public.categories where slug = 'boards'), 'arduino-uno-r3', 'Arduino Uno (R3)', 'A000066', '가장 대중적인 입문용 정품 보드. ATmega328P 기반.', 29000, 120, '{"MCU":"ATmega328P","동작 전압":"5V","디지털 I/O":"14핀","아날로그 입력":"6핀","플래시":"32KB","크기":"68.6 x 53.4 mm"}'::jsonb, '/images/products/arduino-uno-r3.jpg', '{"author":"SparkFun Electronics from Boulder, USA","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Arduino_Uno_-_R3.jpg"}'::jsonb, true),
  ((select id from public.categories where slug = 'boards'), 'arduino-uno-r4-wifi', 'Arduino UNO R4 WiFi', 'ABX00087', 'RA4M1 + ESP32-S3, Wi-Fi·BLE 내장, 12x8 LED 매트릭스.', 38300, 60, '{"MCU":"Renesas RA4M1 (48MHz)","무선":"ESP32-S3 Wi-Fi + BLE","메모리":"256KB Flash / 32KB RAM","포트":"USB-C","입력 전압":"최대 24V"}'::jsonb, '/images/products/arduino-uno-r4-wifi.jpg', '{"author":"Lomrjyo","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Arduino_UNO_R4_WiFi.jpg"}'::jsonb, true),
  ((select id from public.categories where slug = 'boards'), 'arduino-uno-r4-minima', 'Arduino UNO R4 Minima', 'ABX00080', 'R3 대비 메모리·클럭이 향상된 32비트 우노.', 24500, 70, '{"MCU":"Renesas RA4M1 (Cortex-M4, 48MHz)","메모리":"256KB Flash / 32KB RAM","포트":"USB-C","기타":"12-bit DAC, CAN BUS, OP AMP"}'::jsonb, '/images/products/arduino-uno-r4-minima.webp', '{"author":"Arduino","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Arduino_Uno_R4_Minima_perspective.webp"}'::jsonb, false),
  ((select id from public.categories where slug = 'boards'), 'arduino-mega-2560-r3', 'Arduino Mega 2560 (R3)', 'A000067', '핀이 많이 필요한 프로젝트를 위한 대형 보드.', 59000, 40, '{"MCU":"ATmega2560","동작 전압":"5V","디지털 I/O":"54핀","아날로그 입력":"16핀","플래시":"256KB"}'::jsonb, '/images/products/arduino-mega-2560-r3.jpg', '{"author":"Dsimic","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Arduino_MEGA_2560_R3,_front_side.jpg"}'::jsonb, true),
  ((select id from public.categories where slug = 'boards'), 'arduino-nano', 'Arduino Nano', 'A000005', '브레드보드에 바로 꽂는 소형 정품 보드.', 34000, 80, '{"MCU":"ATmega328","동작 전압":"5V","입력 전압":"7-12V","포트":"Mini-B USB","크기":"18 x 45 mm"}'::jsonb, '/images/products/arduino-nano.jpg', '{"author":"MegaMegaAndOmega","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Arduino_Nano_on_table.jpg"}'::jsonb, false),
  ((select id from public.categories where slug = 'boards'), 'arduino-nano-every', 'Arduino Nano Every', 'ABX00028', 'ATmega4809 기반의 작고 강력한 나노.', 18900, 90, '{"MCU":"ATmega4809","동작 전압":"5V","크기":"18 x 45 mm"}'::jsonb, '/images/products/arduino-nano-every.png', '{"author":"Enirstad","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Arduino_Nano_Every.png"}'::jsonb, false),
  ((select id from public.categories where slug = 'boards'), 'arduino-nano-33-iot', 'Arduino Nano 33 IoT', 'ABX00027', 'Wi-Fi·BLE와 6축 IMU를 내장한 IoT용 나노.', 31900, 45, '{"MCU":"SAMD21 Cortex-M0+","무선":"Wi-Fi + Bluetooth","센서":"6축 IMU","동작 전압":"3.3V"}'::jsonb, '/images/products/arduino-nano-33-iot.png', '{"author":"Enirstad","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Arduino_Nano_IOT.png"}'::jsonb, false),
