  ((select id from public.categories where slug = 'boards'), 'arduino-due', 'Arduino Due', 'A000062', '32비트 ARM Cortex-M3 기반 고성능 보드.', 69000, 15, '{"MCU":"Atmel SAM3X8E (Cortex-M3)","동작 전압":"3.3V","클럭":"84MHz"}'::jsonb, '/images/products/arduino-due.jpg', '{"author":"Arduino SA","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:ArduinoDue_Front.jpg"}'::jsonb, false),
